                    return;
                }
                if (Boolean.TRUE.equals(approved)) {
                    action.proceed();
                } else {
                    // Stash the source view so beforeEnter can redirect back.
                    pendingCancelRedirect = getClass();
                    action.proceed();
                }
            })));
