+package com.example.contact;
+
+import org.springframework.stereotype.Service;
+
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+
+/**
+ * In-memory store shared across all views/sessions for the lifetime of the application.
+ */
+@Service
+public class ContactMessageStore {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    public synchronized List<ContactMessage> getAll() {
+        return Collections.unmodifiableList(new ArrayList<>(messages));
+    }
+}
