+        assertTrue(getPage().getByRole(AriaRole.LINK, new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).isVisible());
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertEnabled();
+    }
+
+    @Test
+    void send_blankForm_showsValidationErrors() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+    }
+
+    @Test
+    void send_validForm_sendsAndUpdatesGridAndDisablesSend() {
