+
+        NotificationElement notification = NotificationElement.getByText(getPage(), "Message sent");
+        notification.assertOpen();
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+
+        send().assertDisabled();
+
+        grid.assertRowCount(before + 1);
+        grid.assertCellContent(0, "Name", "Ada Lovelace");
