+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    @Test
+    void initialState_headingLinkAndEmptyEnabledForm() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", test(find(H1.class).single()).getText());
+        assertTrue(find(RouterLink.class).withText("About").exists());
+
+        assertTrue(test(name()).getComponent().isEmpty());
+        assertTrue(test(email()).getComponent().isEmpty());
+        assertTrue(test(phone()).getComponent().isEmpty());
+        assertTrue(test(message()).getComponent().isEmpty());
+        assertTrue(test(send()).isUsable());
+    }
+
+    @Test
+    void aboutView_hasHeading() {
+        navigate(AboutView.class);
+        assertEquals("About", test(find(H1.class).single()).getText());
+    }
+
+    @Test
+    void send_blankForm_marksNameEmailAndMessageInvalid() {
+        navigate(ContactView.class);
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void send_invalidEmailFormat_marksEmailInvalid() {
+        navigate(ContactView.class);
+
+        test(name()).setValue("Ada");
+        test(email()).setValue("not-an-email");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+    }
+
+    @Test
+    void send_messageTooLong_marksMessageInvalid() {
+        navigate(ContactView.class);
+
+        test(name()).setValue("Ada");
+        test(phone()).setValue("12345");
+        test(message()).setValue("x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+    }
+
+    @Test
+    void send_validWithPhoneOnly_sendsAndClearsFormAndDisablesSendUntilEdit() {
+        navigate(ContactView.class);
+        int before = find(Grid.class).single().getListDataView().getItemCount();
+
+        test(name()).setValue("Ada Lovelace");
+        test(phone()).setValue("555-1234");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        Notification notification = find(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertTrue(test(name()).getComponent().isEmpty());
+        assertTrue(test(email()).getComponent().isEmpty());
+        assertTrue(test(phone()).getComponent().isEmpty());
+        assertTrue(test(message()).getComponent().isEmpty());
+
+        assertFalse(test(send()).isUsable());
+
+        Grid<ContactMessage> grid = find(Grid.class).single();
+        assertEquals(before + 1, grid.getListDataView().getItemCount());
+        ContactMessage first = grid.getListDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Ada Lovelace", first.name());
+        assertEquals("Hello there", first.message());
+
+        test(name()).setValue("Someone else");
+        assertTrue(test(send()).isUsable());
+    }
+
+    @Test
+    void send_validWithEmailOnly_andEnterKey_sends() {
+        navigate(ContactView.class);
+
+        test(name()).setValue("Grace Hopper");
+        test(email()).setValue("grace@example.com");
+        test(message()).setValue("Hi!");
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void newMessage_isFirstRow_newestFirst() {
+        navigate(ContactView.class);
+
+        test(name()).setValue("First Person");
+        test(phone()).setValue("111");
+        test(message()).setValue("first message");
+        test(send()).click();
+
+        test(name()).setValue("Second Person");
+        test(phone()).setValue("222");
+        test(message()).setValue("second message");
+        test(send()).click();
+
+        Grid<ContactMessage> grid = find(Grid.class).single();
+        ContactMessage first = grid.getListDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Second Person", first.name());
+    }
+
+    @Test
+    void leavingWithUnsavedInput_showsDialog_keepEditingStaysOnView() {
+        ContactView view = navigate(ContactView.class);
+        test(name()).setValue("Someone");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        Dialog dialog = find(Dialog.class).single();
+        assertTrue(test(dialog).isUsable());
+
+        test(find(Button.class).withText("Keep editing").single()).click();
+
+        assertTrue(getCurrentView() == view || getCurrentView().getClass() == ContactView.class);
+        assertEquals("Someone", test(name()).getComponent().getValue());
+    }
+
+    @Test
+    void leavingWithUnsavedInput_discardNavigatesAway() {
+        navigate(ContactView.class);
+        test(name()).setValue("Someone");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        test(find(Button.class).withText("Discard").single()).click();
+
+        assertEquals(AboutView.class, getCurrentView().getClass());
+    }
+
+    @Test
+    void leavingWithEmptyForm_noDialog() {
+        navigate(ContactView.class);
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertFalse(find(Dialog.class).exists());
+        assertEquals(AboutView.class, getCurrentView().getClass());
+    }
+}
